<?php
/**
 * FIX RANKING ALFA - Self-contained controller deployer  
 * Upload to sijamaah.rf.gd, visit once, then DELETE immediately.
 * This script writes the PresensiSholatController.php and self-deletes.
 */
@set_time_limit(300);
header('Content-Type: text/plain; charset=utf-8');
error_reporting(E_ERROR | E_PARSE);

echo "=== FIX RANKING ALFA ===\n\n";

$controllerCode = base64_decode();

if (!$controllerCode || strlen($controllerCode) < 100) {
    echo "ERROR: Could not decode controller.\n";
    exit(1);
}

echo "Controller decoded: " . strlen($controllerCode) . " bytes\n";

/* ---------- Find app root ---------- */
function looksLikeAppRoot($d) {
    return @is_dir($d . '/resources') && @is_dir($d . '/vendor') && @is_file($d . '/index.php');
}
$target = null;
foreach ([__DIR__, dirname(__DIR__)] as $base) {
    if (@looksLikeAppRoot($base)) { $target = $base; break; }
    foreach ((array)@scandir($base) as $entry) {
        if ($entry[0] === '.') continue;
        $c = $base . '/' . $entry;
        if (@looksLikeAppRoot($c)) { $target = $c; break 2; }
    }
}
if (!$target) { exit("ERROR: Laravel app root not found.\n"); }

echo "App root: $target\n";

/* ---------- Write controller ---------- */
$dest = $target . '/app/Http/Controllers/PresensiSholatController.php';
if (file_put_contents($dest, $controllerCode) !== false) {
    echo "SUCCESS: Controller written\n";
} else {
    echo "FAILED: Could not write controller\n";
    exit(1);
}

/* ---------- Clear caches ---------- */
exec('php ' . $target . '/artisan config:clear 2>&1', $out1);
exec('php ' . $target . '/artisan view:clear 2>&1', $out2);
echo "Cache cleared\n";

echo "\n=== DONE ===\n";
echo "Test: https://sijamaah.rf.gd/ranking-alfa\n";
echo "DELETE this file after testing!\n";
@unlink(__FILE__);
